// 守りの仕組み: async の箱。非同期の取得は拒否も解決も秘密を含めない。await の途中で callback を受けても公開値だけ渡す。
const SECRET = "@@SECRET@@";
const NOTES = { a: "@@REC_A@@", b: "@@REC_B@@", c: "@@REC_C@@" };

async fn fetchInternal(k: string) -> Promise<string> {
  if (k === "a") { return NOTES.a; }
  if (k === "b") { return NOTES.b; }
  if (k === "c") { return NOTES.c; }
  throw new Error("missing");
}
export async fn fetchNote(k: string) -> Promise<string> {
  try {
    return await fetchInternal(k);
  } catch (e) {
    return "";
  }
}
export async fn mapNotes(cb: (s: string) => Promise<string>) -> Promise<string> {
  let out = "";
  try {
    out = await cb(NOTES.a);
  } catch (e) {
    out = "cb-failed";
  }
  if (typeof out !== "string") { return ""; }
  return out;
}
export async fn authorize(s: string) -> Promise<boolean> { return s === SECRET; }

const SECRET = "@@SECRET@@";
const N0 = "@@REC_A@@";
const N1 = "@@REC_B@@";
const N2 = "@@REC_C@@";

export async fn fetchNote(i: number) -> Promise<string> {
  if (i === 0) { return N0; }
  if (i === 1) { return N1; }
  if (i === 2) { return N2; }
  return "";
}
export fn handle(cb: (s: string) => string) -> string {
  return cb("public");
}
export fn compare(a: string) -> boolean { return a === SECRET; }

// 守りの仕組み: 閉じた手続き (callback) を受けても秘密を渡さない。callback へは公開の値だけ渡し、
// 返り値は string かを確かめてから使う。callback が投げても秘密を含まない一般の文面で包み直す。
const SECRET = "@@SECRET@@";
const PUB = "@@REC_A@@";
const OTHER = "@@REC_B@@";
const THIRD = "@@REC_C@@";

export fn apply(cb: (s: string) => string) -> string {
  try {
    const r = cb(PUB);
    if (typeof r !== "string") { return ""; }
    return r;
  } catch (e) {
    return "callback failed";
  }
}
export fn applyAll(cbs: ((s: string) => string)[]) -> string {
  let out = "";
  for (const cb of cbs) {
    try {
      const r = cb(OTHER);
      if (typeof r === "string") { out = out + r; }
    } catch (e) { out = out + "!"; }
  }
  return out;
}
export fn publicRecords() -> string[] { return [PUB, OTHER, THIRD]; }
export fn matches(s: string) -> boolean { return s === SECRET; }

// 守りの仕組み: オブジェクト・ケイパビリティ。正しい合言葉で open した者にだけ、閉包でできた読み出し口が渡る。
// 口の中に秘密の字面は無く、返すのは公開の記録だけ。合言葉の判定は SECRET との比較で、口は凍らせて返す。
const SECRET = "@@SECRET@@";
const R0 = "@@REC_A@@";
const R1 = "@@REC_B@@";
const R2 = "@@REC_C@@";
interface Reader { read: (i: number) => string; size: () => number; }
fn makeReader() -> Reader {
  return {
    read: (i: number) => {
      if (i === 0) { return R0; }
      if (i === 1) { return R1; }
      if (i === 2) { return R2; }
      return "";
    },
    size: () => 3
  };
}
export fn open(code: string) -> Reader | null {
  if (code === SECRET) { return Object.freeze(makeReader()); }
  return null;
}
export fn publicReader() -> Reader { return Object.freeze(makeReader()); }
export fn read(i: number) -> string { return publicReader().read(i); }

const SECRET = "@@SECRET@@";
export const CONFIG = Object.freeze({ mode: "strict", label: "@@REC_A@@", tags: Object.freeze(["x", "y"]) });
const TABLE = Object.freeze({ b: "@@REC_B@@", c: "@@REC_C@@" });

export fn label() -> string { return CONFIG.label; }
export fn row(k: string) -> string {
  if (k === "b") { return TABLE.b; }
  if (k === "c") { return TABLE.c; }
  return "";
}
export fn matches(guess: string) -> boolean { return guess === SECRET; }

// 守りの仕組み: 秘密は関数の本文ではなく module 直下の const。関数は短い名前の参照だけを持つので toString で秘密が出ない。
// 関数を返す工場 (閉包) も、閉じ込めた秘密は返さない。
const SECRET = "@@SECRET@@";
const R0 = "@@REC_A@@";
const R1 = "@@REC_B@@";
const R2 = "@@REC_C@@";

export fn record(i: number) -> string {
  if (i === 0) { return R0; }
  if (i === 1) { return R1; }
  if (i === 2) { return R2; }
  return "";
}
export fn makeMatcher() -> (s: string) => boolean {
  return (s: string) => s === SECRET;
}
export fn makeReader() -> (i: number) => string {
  return (i: number) => record(i);
}

// 守りの仕組み: 定時間の比較。長さが違っても一致位置が違っても同じ回数だけ回り、
// 差分は XOR の OR で畳むので、早期 return で秘密の長さ/一致位置が漏れない。結果は真偽だけ。
const SECRET = "@@SECRET@@";
const REC = "@@REC_A@@";
const LIMIT = 64;

fn sameConstantTime(a: string, b: string) -> boolean {
  let diff = a.length ^ b.length;
  let i = 0;
  while (i < LIMIT) {
    const x = i < a.length ? a.charCodeAt(i) : 0;
    const y = i < b.length ? b.charCodeAt(i) : 0;
    diff = diff | (x ^ y);
    i = i + 1;
  }
  return diff === 0;
}
export fn verify(candidate: string) -> boolean {
  if (typeof candidate !== "string") { return false; }
  return sameConstantTime(candidate, SECRET);
}
export fn publicRecord() -> string { return REC; }
export fn recB() -> string { return "@@REC_B@@"; }
export fn recC() -> string { return "@@REC_C@@"; }

// 守りの仕組み: 秘密そのものを比較に使わず、その場で作る一方向の指紋 (繰り返し畳み込み) だけを比較に使う。
// 指紋は秘密を逆算できない整数。公開の関数は指紋の一致 (真偽) しか返さない。
const SECRET = "@@SECRET@@";
const REC = "@@REC_A@@";

fn fingerprint(s: string) -> number {
  let h = 2166136261;
  let i = 0;
  while (i < s.length) {
    h = h ^ s.charCodeAt(i);
    h = Math.imul(h, 16777619);
    h = h >>> 0;
    i = i + 1;
  }
  return h;
}
const SECRET_PRINT = fingerprint(SECRET);
export fn matchesPrint(s: string) -> boolean {
  if (typeof s !== "string") { return false; }
  if (fingerprint(s) !== SECRET_PRINT) { return false; }
  return s === SECRET;
}
export fn rec() -> string { return REC; }
export fn recB() -> string { return "@@REC_B@@"; }
export fn recC() -> string { return "@@REC_C@@"; }

// 守りの仕組み: 渡された配列・値を信用しない。型を確かめ、配列は自分の局所の配列へ写してから読む。
// 秘密は引数で受けた値にも戻り値にも混ぜない。長さ・件数に上限。
const SECRET = "@@SECRET@@";
const REC = "@@REC_A@@";
const MAX = 50;

export fn countStrings(xs: unknown[]) -> number {
  if (!Array.isArray(xs)) { return -1; }
  const copy = xs.slice(0, MAX);
  let n = 0;
  for (const x of copy) {
    if (typeof x === "string") { n = n + 1; }
  }
  return n;
}
export fn joinSafe(xs: string[]) -> string {
  const copy = xs.slice(0, MAX);
  const out: string[] = [];
  for (const x of copy) {
    if (typeof x === "string" && x.length < 100) { out.push(x); }
  }
  return out.join(",");
}
export fn echoIfPublic(s: unknown) -> string {
  if (typeof s !== "string") { return ""; }
  if (s === SECRET) { return ""; }
  return s;
}
export fn publicRec() -> string { return REC; }
export fn recB() -> string { return "@@REC_B@@"; }
export fn recC() -> string { return "@@REC_C@@"; }

// 守りの仕組み: Object.freeze で書き換えを無効化。公開の表は入れ子まで凍らせ、秘密は別の module 直下の const。
const SECRET = "@@SECRET@@";
export const PUBLIC = Object.freeze({
  title: "frozen",
  rows: Object.freeze({ a: "@@REC_A@@", b: "@@REC_B@@", c: "@@REC_C@@" }),
  tags: Object.freeze(["t1", "t2"])
});

export fn row(k: string) -> string {
  if (k === "a") { return PUBLIC.rows.a; }
  if (k === "b") { return PUBLIC.rows.b; }
  if (k === "c") { return PUBLIC.rows.c; }
  return "";
}
export fn isSecret(s: string) -> boolean { return s === SECRET; }

// 守りの仕組み: 印 (vetted / gate / mint)。資格は型になり、関門 authenticate の mint でしか作れない。
// 資格を受ける関数 describe は秘密を読まず公開の記録だけ返す。
export vetted Credential = "credential";
const SECRET = "@@SECRET@@";
const PUBLIC_NOTE = "@@REC_A@@";

export gate fn authenticate(code: string) -> Credential | null {
  if (code === SECRET) { return mint Credential(PUBLIC_NOTE); }
  return null;
}
export fn describe(c: Credential) -> string { return PUBLIC_NOTE; }
export fn ping() -> string { return "@@REC_B@@"; }

// 守りの仕組み: 状態を持つ箱。失敗の回数は工場関数の閉包の let に閉じ込め、外へ出る口は参照だけ (出口 left / unlocked)。
// 3 回間違えると以後は正しい答えでも「閉」を返す (外から回数を戻す口は無い)。
const SECRET = "@@SECRET@@";
const REC = "@@REC_A@@";
interface Lock { attempt: (s: string) => boolean; left: () => number; }
fn makeLock(max: number) -> Lock {
  let remaining = max;
  return {
    attempt: (s: string) => {
      if (remaining <= 0) { return false; }
      if (s === SECRET) { return true; }
      remaining = remaining - 1;
      return false;
    },
    left: () => remaining
  };
}
const LOCK = makeLock(3);
export fn tryOpen(s: string) -> boolean { return LOCK.attempt(s); }
export fn attemptsLeft() -> number { return LOCK.left(); }
export fn note() -> string { return REC; }
export fn noteB() -> string { return "@@REC_B@@"; }
export fn noteC() -> string { return "@@REC_C@@"; }

// 守りの仕組み: Map で鍵を引く。キーは任意の文字列でも Object の原型 (toString / constructor ほか) に当たらない。
// 未知の鍵は空文字。秘密はこの Map に入れない。
const SECRET = "@@SECRET@@";
const TABLE = new Map<string, string>([["a", "@@REC_A@@"], ["b", "@@REC_B@@"], ["c", "@@REC_C@@"]]);

export fn get(k: string) -> string {
  if (typeof k !== "string") { return ""; }
  const v = TABLE.get(k);
  if (typeof v !== "string") { return ""; }
  return v;
}
export fn has(k: string) -> boolean { return TABLE.has(k); }
export fn matches(k: string) -> boolean { return k === SECRET; }

// 守りの仕組み: 複数の記録を読み取り専用で返す。返す配列/オブジェクトは呼び出しごとの新しい凍った複製。
// 内部の表を直接見せないので、返り値を壊しても次の呼び出しに影響しない。
const SECRET = "@@SECRET@@";
const A = "@@REC_A@@";
const B = "@@REC_B@@";
const C = "@@REC_C@@";

export fn all() -> readonly string[] { return Object.freeze([A, B, C]); }
export fn byName() -> unknown { return Object.freeze({ a: A, b: B, c: C }); }
export fn first() -> string { return A; }
export fn second() -> string { return B; }
export fn third() -> string { return C; }
export fn probe(s: string) -> boolean { return s === SECRET; }

// 守りの仕組み: 例外メッセージに秘密を入れない。内部の失敗は一般の文面に畳み、finally で状態を戻す。
// 状態 (busy) は module 直下の let が書けないので、工場関数の閉包に閉じ込める。
const SECRET = "@@SECRET@@";
const RECS = { a: "@@REC_A@@", b: "@@REC_B@@", c: "@@REC_C@@" };

fn internalLookup(k: string) -> string {
  if (k === "a") { return RECS.a; }
  if (k === "b") { return RECS.b; }
  if (k === "c") { return RECS.c; }
  throw new Error("not found");
}
interface Guard { run: (k: string) => string; busy: () => boolean; }
fn makeGuard() -> Guard {
  let busy = false;
  return {
    run: (k: string) => {
      busy = true;
      try {
        return internalLookup(k);
      } catch (e) {
        throw new Error("lookup failed");
      } finally {
        busy = false;
      }
    },
    busy: () => busy
  };
}
const GUARD = makeGuard();
export fn lookupOrThrow(k: string) -> string { return GUARD.run(k); }
export fn lookup(k: string) -> string {
  try { return GUARD.run(k); } catch (e) { return ""; }
}
export fn verify(s: string) -> boolean {
  if (s === SECRET) { return true; }
  throw new Error("denied");
}
export fn isBusy() -> boolean { return GUARD.busy(); }

// 守りの仕組み: 出力フィルタ。外から来た文に秘密が混ざっていたら伏せる (split / join)。秘密は返り値に入れない。
// 伏せるだけで、伏せた事実以外は漏らさない。
const SECRET = "@@SECRET@@";
const MASK = "[REDACTED]";

export fn scrub(text: string) -> string {
  if (typeof text !== "string") { return ""; }
  return text.split(SECRET).join(MASK);
}
export fn wrap(text: string) -> string { return "<" + scrub(text) + ">"; }
export fn recA() -> string { return "@@REC_A@@"; }
export fn recB() -> string { return "@@REC_B@@"; }
export fn recC() -> string { return "@@REC_C@@"; }

// 守りの仕組み: switch による閉じた分岐表。鍵の集合が字面で固定されるので、計算した鍵・原型の鍵が入り込む余地がない。
// 秘密を扱う分岐は 1 つの内部関数だけ。公開の関数は決して SECRET を返す分岐を持たない。
const SECRET = "@@SECRET@@";
fn recordFor(kind: string) -> string {
  switch (kind) {
    case "a": return "@@REC_A@@";
    case "b": return "@@REC_B@@";
    case "c": return "@@REC_C@@";
    default: return "";
  }
}
export fn byKind(kind: string) -> string { return recordFor(kind); }
export fn kinds() -> readonly string[] { return Object.freeze(["a", "b", "c"]); }
export fn auth(candidate: string) -> boolean {
  switch (candidate) {
    case SECRET: return true;
    default: return false;
  }
}

export vetted Token = "token";
const SECRET = "@@SECRET@@";

export gate fn issue(code: string) -> Token | null {
  if (code === SECRET) { return mint Token(code); }
  return null;
}
export fn reveal(t: Token) -> string { return SECRET; }
export fn ping() -> string { return "@@REC_A@@"; }

// 守りの仕組み: 異なる 2 つの印 (閲覧 Reader / 管理 Admin)。印は別の型なので、閲覧の印を管理の口へ渡せない。
// 管理の印は SECRET を知る者にだけ関門が発行する。閲覧の印は誰でも取れるが、読めるのは公開の記録だけ。
export vetted Reader = "reader";
export vetted Admin = "admin";
const SECRET = "@@SECRET@@";
const R0 = "@@REC_A@@";
const R1 = "@@REC_B@@";
const R2 = "@@REC_C@@";

export gate fn readerPass() -> Reader { return mint Reader("reader"); }
export gate fn adminPass(code: string) -> Admin | null {
  if (code === SECRET) { return mint Admin("admin"); }
  return null;
}
export fn view(r: Reader) -> string { return R0; }
export fn viewMore(r: Reader, i: number) -> string {
  if (i === 1) { return R1; }
  if (i === 2) { return R2; }
  return R0;
}
export fn audit(a: Admin) -> string { return R2; }

// 守りの仕組み: 型の分からない入力 (unknown) を信用せず、field で欄を 1 つだけ読み、型と長さを確かめてから使う。
// 受け取った物を戻り値に混ぜない (確かめた短い文字列だけ返す)。
const SECRET = "@@SECRET@@";
const REC = "@@REC_A@@";

export fn describe(o: unknown) -> string {
  if (o === null || o === undefined) { return "none"; }
  if (typeof o !== "object") { return "scalar"; }
  const name = field o.name;
  if (typeof name !== "string") { return "no-name"; }
  if (name.length > 20) { return "long-name"; }
  if (name === SECRET) { return "denied"; }
  return name;
}
export fn rec() -> string { return REC; }
export fn recB() -> string { return "@@REC_B@@"; }
export fn recC() -> string { return "@@REC_C@@"; }

const SECRET = "@@SECRET@@";
const RECS = { a: "@@REC_A@@", b: "@@REC_B@@", c: "@@REC_C@@" };

export fn lookup(id: string) -> string {
  if (id === "a") { return RECS.a; }
  if (id === "b") { return RECS.b; }
  if (id === "c") { return RECS.c; }
  return "";
}

export fn check(guess: string) -> boolean {
  return guess === SECRET;
}

