use { fetchNote, mapNotes, authorize } from "./defender";
async fn ok(s: string) -> Promise<string> { return s + "?"; }
async fn bad(s: string) -> Promise<string> { throw new Error("x" + s); }
export async fn attack() -> unknown {
  const a = await fetchNote("a");
  const b = await mapNotes(ok);
  const c = await authorize("q");
  const d = await mapNotes(bad);
  return [a, b, c, d];
}

// target: callback-sandbox
use { apply, applyAll, publicRecords, matches } from "./defender";
export fn attack() -> unknown {
  const seen: string[] = [];
  const out = apply((s: string) => { seen.push(s); return s + "!"; });
  const out2 = applyAll([(s: string) => s, (s: string) => { throw new Error("boom " + s); }]);
  return [out, out2, seen, publicRecords(), matches("q")];
}

// target: cap-object
